const MovementUpdate  = ({ data, confirm }) => {
	const [, set_obs] = useState(1);
	const [view, setView] = useState(2)




	let location = useLocation();

	const searchHash = location.search?.split("?")?.[1];
	const router = parseQuery(searchHash);

	let cId = router?.cId;

	

	const close  = ()  => {
		if(isValidFunction(confirm)){
			confirm()
		};
		data?.modalID && CloseModal({id:data?.modalID});
	}


	const updView  = (v)  => {
		setView(v)
	}


	return (
		<div style={{
			height: getStore("isOS")? "89vh" : "94vh",
			marginTop: getStore("isOS")? "9vh" : "6vh",
			width: "94vw",
			overflow: "auto",
			background: "var(--dark-800)",
			borderRadius: 13,
			padding: "12px 6px 20px"
		}}>
		<div className=" " style={{marginBottom: 24}}>

			<div className="h23g9woI">
				<div className="jKZvHt " onClick={close}>
						<Svg
							name={"arrowBack"} 
							size={22}
							color={"var(--light-200)"}
						/>
						<div className="eULkqP"></div>
				</div>
				<div className="flexSpace"/>
				{getStore("image_preview_mov") ? 
				<div className={`icon_action ${view===1?"active":""} `}	onClick={()=>updView(1)}>
					<Svg name={"image_outline"}	color={"var(--light-200)"}/>
				</div>
				:null}
				<div className={`icon_action ${view===2?"active":""} `} onClick={()=>updView(2)}>
					<Svg name={"list_form"} color={"var(--light-200)"}/>
				</div>
			</div>
				
			<div style={{paddingTop: 4}}/>

			<OpacityView viewId={1} activeView={view}>
				<ImageUpdateView  />
			</OpacityView>
			
			<OpacityView viewId={2} activeView={view}>
				<FormUpdateView  close={close}/>
			</OpacityView>
			

			</div>
		</div>
	)

}

export default MovementUpdate;







