const FormUpdateView  = ({  activeView, close }) => {

	
	const [, set_obs] = useState(1);

	const updObs =  () => {
		set_obs(gen16CodeId())
	}	

	
	
	let flds = [
		"title",
		"description",
		"document",
		"amount",
		"categoryId",
		"imagePath"
	]

	let diff = compareJSON(flds,getStore(frmNm),getStore(frmNm + "_bck") )





	const fetchData  = async (bdyq2)  => {
		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		setTimeout(() => {
			let ignoreMemo = getStore("ignoreMemo") || {};
			ignoreMemo[bdyq2.params.movementId] = 2;
			updStore("ignoreMemo", ignoreMemo);
		}, 100);
		if (td && !td.error) {
			close(true);
		}
	}

	const save  = async ()  => {

		let diff = compareJSON(flds,getStore(frmNm),getStore(frmNm + "_bck") )
		
		let bdyq2 = {...getStore(qryStore())?.upd__incms_expns};
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId,
			"movementId": getStore(frmNm)?.["movementId"],
			year:getStore("date_current_year"),
		}
		bdyq2.data2update = diff.data;	

		fetchData(bdyq2)
		//console.log(bdyq2)
	};



	const updCategory = (v) => {
		updFrm("categoryId",v);
	}


	const updFrm = (f, v) => {
		let frm2 = getStore(frmNm) || {};
		frm2[f] = v;
		updStore(frmNm, frm2);
		set_obs(gen16CodeId())
	};



	const viewCategories =  (v) => {
		let data = {};
		data["zIndex"] = 480;
		// data['observeResize']=true;
		data["props"] = { minHeight: "1vh", overlay: true };
		data["content"] = <Categories2Filter 
			type={getStore(frmNm)?.movementType + "s"}
			confirm={updCategory} 
			init={getStore(frmNm)?.categoryId}
		/>
		OpenModal(data);
	}

	
	let categoryLabel = getStore("categories_ids")?.[getStore(frmNm)?.categoryId]?.name;
	


	return (
		<div style={{maxWidth: 560 ,    height: "90vmin", padding: "5px!important"}}>
				<div className="_dsplFlx " style={{padding: 9}}>
					
					<div className="flexSpace"/>
					{diff.hasChange?
					<div className="">
						<GrayButton color={"#007bfc"} label={getFNMLabels(43)} clickHandler={save}/>
					</div>
					:null}
				</div>

				<div className="scollVh min88">
					
					<div className="_dsplFlx  spaceAround flxWrp" >
					
						<DarkCard
							icon={"groups"}
							label={getFNMLabels(54)}
							value={categoryLabel || getFNMLabels(45) }
							handleClick={viewCategories}
						/>
					</div>
					<div className="_dsplFlx  spaceAround flxWrp" >
							
							
						
							<LabelInput 
								title={getFNMLabels(50)}
								frmNm={frmNm}
								keyfld={"title"}
								updObs={updObs}
							/>
							
							<LabelInput 
								title={getFNMLabels(51)}
								frmNm={frmNm}
								keyfld={"amount"}
								updObs={updObs}
							/>
							<LabelInput 
								title={getFNMLabels(52)}
								frmNm={frmNm}
								keyfld={"document"}
								updObs={updObs}
							/>
							<LabelInput 
								title={getFNMLabels(53)}
								frmNm={frmNm}
								keyfld={"description"}
								updObs={updObs}
								isTxtArea={true}
							/>
							
						
					</div>
				</div>
			</div>
	)

}







